-- Volcando estructura para tabla sys_polleria.pedidos
CREATE TABLE IF NOT EXISTS `pedidos` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `tipo` enum('mesa','llevar','delivery') NOT NULL DEFAULT 'mesa',
  `mesa_id` int unsigned DEFAULT NULL,
  `cliente_id` int unsigned DEFAULT NULL,
  `usuario_id` int unsigned DEFAULT NULL,
  `caja_id` int unsigned DEFAULT NULL,
  `repartidor_id` int unsigned DEFAULT NULL,
  `estado` enum('abierto','pagado','anulado') NOT NULL DEFAULT 'abierto',
  `delivery_estado` enum('pendiente','en_camino','entregado','cancelado') DEFAULT NULL,
  `direccion_entrega` varchar(220) DEFAULT NULL,
  `telefono_entrega` varchar(30) DEFAULT NULL,
  `comprobante` enum('ticket','boleta','factura') DEFAULT NULL,
  `serie` varchar(10) DEFAULT NULL,
  `numero` int unsigned DEFAULT NULL,
  `subtotal` decimal(12,2) NOT NULL DEFAULT '0.00',
  `descuento` decimal(12,2) NOT NULL DEFAULT '0.00',
  `costo_delivery` decimal(12,2) NOT NULL DEFAULT '0.00',
  `igv` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total` decimal(12,2) NOT NULL DEFAULT '0.00',
  `notas` varchar(250) DEFAULT NULL,
  `motivo_anulacion` varchar(200) DEFAULT NULL,
  `fecha_pedido` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_pago` datetime DEFAULT NULL,
  `fe_estado` enum('pendiente','aceptado','rechazado','error','anulado') DEFAULT NULL,
  `fe_mensaje` varchar(250) DEFAULT NULL,
  `fe_hash` varchar(80) DEFAULT NULL,
  `fe_enlace` varchar(255) DEFAULT NULL,
  `fe_qr` varchar(500) DEFAULT NULL,
  `fe_fecha` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ped_estado` (`estado`,`fecha_pago`),
  KEY `idx_ped_mesa` (`mesa_id`),
  KEY `idx_ped_tipo` (`tipo`,`delivery_estado`),
  KEY `fk_ped_cli` (`cliente_id`),
  KEY `fk_ped_usr` (`usuario_id`),
  KEY `fk_ped_rep` (`repartidor_id`),
  CONSTRAINT `fk_ped_cli` FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ped_mesa` FOREIGN KEY (`mesa_id`) REFERENCES `mesas` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ped_rep` FOREIGN KEY (`repartidor_id`) REFERENCES `repartidores` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ped_usr` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=943 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

